def transform(grid):
    from collections import Counter, deque

    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [[bg] * w for _ in range(h)]

    # Repeated-color rectangular patches are the objects; isolated colored
    # cells are noise. Use 8-connectivity so a noise cell inside a patch
    # does not split it into separate components.
    for color in set(v for row in grid for v in row if v != bg):
        seen = set()
        for r in range(h):
            for c in range(w):
                if grid[r][c] != color or (r, c) in seen:
                    continue
                q = deque([(r, c)])
                seen.add((r, c))
                cells = []
                while q:
                    x, y = q.popleft()
                    cells.append((x, y))
                    for dx in (-1, 0, 1):
                        for dy in (-1, 0, 1):
                            if dx == 0 and dy == 0:
                                continue
                            nx, ny = x + dx, y + dy
                            if (0 <= nx < h and 0 <= ny < w
                                    and grid[nx][ny] == color
                                    and (nx, ny) not in seen):
                                seen.add((nx, ny))
                                q.append((nx, ny))

                if len(cells) < 4:
                    continue
                r0 = min(x for x, _ in cells)
                r1 = max(x for x, _ in cells)
                c0 = min(y for _, y in cells)
                c1 = max(y for _, y in cells)
                for x in range(r0, r1 + 1):
                    for y in range(c0, c1 + 1):
                        out[x][y] = color

    return out
